const out = [];
for (let i = 0; i < 10; i++) {
  if (window.__ensemble.getState().settings.onboarded) break;
  const all = [...document.querySelectorAll('button')].filter(b => !b.disabled);
  const find = re => all.find(b => re.test(b.textContent.trim()));
  const b = find(/^(Continue|Start using|Start with|Get started|Start working|Done|Finish|Open Ensemble)/) || find(/^Skip/);
  if (!b) break;
  out.push(b.textContent.trim().slice(0, 30));
  b.click();
  await new Promise(r => setTimeout(r, 900));
}
return 'clicked: ' + out.join(' > ');

window.__S = () => window.__ensemble.getState();
window.__sleep = (ms) => new Promise(r => setTimeout(r, ms));
window.__chat = () => { const s = window.__S(); return s.chats.find(c => c.id === s.chatId) };
window.__busy = () => Object.values(window.__S().agents).filter(a => a.chatId === window.__S().chatId && a.phase !== 'idle' && a.phase !== 'error').length;
window.__bottom = () => { const sc = document.querySelector('[data-view-scope]')?.parentElement; if (sc) sc.scrollTop = sc.scrollHeight; };
window.__waitIdle = async (max) => { const t0 = Date.now(); while (Date.now() - t0 < max) { await window.__sleep(500); if (window.__busy() === 0) return Math.round((Date.now() - t0) / 1000) + 's'; } return 'still busy'; };
window.__counts = () => {
  const strip = document.querySelector('[data-network-strip] > button')?.textContent.replace(/\s+/g, ' ').trim();
  const insp = [...document.querySelectorAll('aside section')].find(x => /In this chat/.test(x.textContent));
  const right = insp ? insp.querySelector('.tabular')?.textContent : '';
  const groups = insp ? [...insp.querySelectorAll('button[aria-expanded]')].map(b => b.textContent.replace(/\s+/g, ' ').trim().slice(0, 30)) : [];
  return 'strip [' + strip + '] inspector [' + right + '] groups [' + groups.join(' | ') + ']';
};
return 'helpers';
